#!/usr/bin/env node
/**
 * FORK 2026-05-11 — auto-generated tinker-ui FORK registry.
 *
 * Greps every `// FORK YYYY-MM-DD:` (and `/* FORK YYYY-MM-DD ...` block
 * variant) comment under `tinker-ui/src/`, aggregates by file, and emits
 * either a markdown table or JSON.
 *
 * Markdown is the default — gets spliced into
 * `TINKER_UI_DESIGN_BIBLE/tinker-ui.md` between marker lines:
 *
 *     <!-- BEGIN GENERATED-FORK-REGISTRY -->
 *     ...
 *     <!-- END GENERATED-FORK-REGISTRY -->
 *
 * Use `--apply` to do the splice in-place. Without `--apply`, prints to
 * stdout so the user can review.
 *
 * Use `--json` for machine-readable output (intended for the merge gate:
 * a fork entry without a corresponding TINKER_UI_DESIGN_BIBLE/tinker-ui.md
 * row should fail).
 */
import { readFile, readdir, stat, writeFile } from "node:fs/promises";
import * as os from "node:os";
import * as path from "node:path";

const TINKER_UI_SRC = path.resolve(os.homedir(), "src/tinkerclaw/tinker-ui/src");
const BIBLE = path.resolve(os.homedir(), "src/tinkerclaw/TINKER_UI_DESIGN_BIBLE/tinker-ui.md");
const FORK_RE = /\bFORK[ ]+(\d{4}-\d{2}-\d{2})\b[: \-—]*(.+?)$/;
const BEGIN_MARK = "<!-- BEGIN GENERATED-FORK-REGISTRY -->";
const END_MARK = "<!-- END GENERATED-FORK-REGISTRY -->";

async function walk(dir, results = []) {
  const entries = await readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.name === "node_modules" || entry.name === "dist" || entry.name.startsWith(".")) {
      continue;
    }
    const p = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      await walk(p, results);
    } else if (/\.(ts|js|css|html)$/.test(entry.name)) {
      results.push(p);
    }
  }
  return results;
}

function extractForkAnchors(text, file) {
  const out = [];
  const lines = text.split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line.includes("FORK")) continue;
    const m = FORK_RE.exec(line);
    if (!m) continue;
    const [, date, summary] = m;
    out.push({
      file: path.relative(path.resolve(TINKER_UI_SRC, ".."), file),
      line: i + 1,
      date,
      summary: summary.trim().slice(0, 160),
    });
  }
  return out;
}

function groupByFile(anchors) {
  const byFile = new Map();
  for (const a of anchors) {
    if (!byFile.has(a.file)) {
      byFile.set(a.file, { file: a.file, count: 0, dates: [], anchors: [] });
    }
    const e = byFile.get(a.file);
    e.count += 1;
    e.dates.push(a.date);
    e.anchors.push(a);
  }
  for (const e of byFile.values()) {
    e.dates.sort();
    e.firstDate = e.dates[0];
    e.lastDate = e.dates[e.dates.length - 1];
  }
  return byFile;
}

function renderMarkdown(byFile, allAnchors) {
  const files = Array.from(byFile.values()).sort((a, b) => {
    if (a.lastDate !== b.lastDate) return b.lastDate.localeCompare(a.lastDate);
    return a.file.localeCompare(b.file);
  });
  const lines = [];
  lines.push("");
  lines.push(
    "> Auto-generated by `scripts/gen-tinker-ui-registry.mjs`. Do not hand-edit between the markers below.",
  );
  lines.push("");
  lines.push(
    `Files with at least one \`// FORK YYYY-MM-DD:\` anchor — sorted by most-recent edit. Total anchors: **${allAnchors.length}** across **${files.length}** files.`,
  );
  lines.push("");
  lines.push("| File | Anchors | First | Last |");
  lines.push("| ---- | ------- | ----- | ---- |");
  for (const e of files) {
    lines.push(`| \`${e.file}\` | ${e.count} | ${e.firstDate} | ${e.lastDate} |`);
  }
  lines.push("");
  return lines.join("\n");
}

async function splice(rendered) {
  const text = await readFile(BIBLE, "utf8");
  const beginIdx = text.indexOf(BEGIN_MARK);
  const endIdx = text.indexOf(END_MARK);
  if (beginIdx < 0 || endIdx < 0) {
    // First-run: add a "Generated registry" section at the end before any trailing newlines.
    const trimmed = text.replace(/\n+$/, "");
    const updated =
      trimmed + "\n\n## Generated FORK registry\n\n" + `${BEGIN_MARK}\n${rendered}\n${END_MARK}\n`;
    await writeFile(BIBLE, updated, "utf8");
    return { mode: "init", inserted: true };
  }
  const before = text.slice(0, beginIdx + BEGIN_MARK.length);
  const after = text.slice(endIdx);
  const updated = `${before}\n${rendered}\n${after}`;
  await writeFile(BIBLE, updated, "utf8");
  return { mode: "splice", inserted: true };
}

async function main() {
  const args = process.argv.slice(2);
  const isJson = args.includes("--json");
  const isApply = args.includes("--apply");

  const files = await walk(TINKER_UI_SRC);
  const allAnchors = [];
  for (const file of files) {
    try {
      const text = await readFile(file, "utf8");
      for (const a of extractForkAnchors(text, file)) {
        allAnchors.push(a);
      }
    } catch {
      // ignore unreadable files (binary, broken symlinks, etc.)
    }
  }
  allAnchors.sort((a, b) => {
    if (a.date !== b.date) return b.date.localeCompare(a.date);
    return a.file.localeCompare(b.file) || a.line - b.line;
  });
  const byFile = groupByFile(allAnchors);

  if (isJson) {
    process.stdout.write(
      JSON.stringify({ total: allAnchors.length, anchors: allAnchors }, null, 2),
    );
    process.stdout.write("\n");
    return;
  }

  const rendered = renderMarkdown(byFile, allAnchors);
  if (isApply) {
    const res = await splice(rendered);
    console.log(
      `[gen-tinker-ui-registry] ${res.mode}: ${allAnchors.length} anchors across ${byFile.size} files.`,
    );
    return;
  }
  process.stdout.write(rendered);
  process.stdout.write("\n");
}

main().catch((err) => {
  console.error(`[gen-tinker-ui-registry] error: ${String(err)}`);
  process.exit(1);
});
